 function Field({label,id,type='text',value,onChange,disabled=false,hint,invalid=false}:{label:string;id:string;type?:string;value?:string;onChange?:(v:string)=>void;disabled?:boolean;hint?:string;invalid?:boolean}){const fieldMockup=useMockup();return <div className="field"><label htmlFor={id}>{label}</label><Input id={id} name={id} type={type} value={value} onChange={e=>onChange?.(e.target.value)} disabled={disabled||fieldMockup.state==='cargando'} aria-invalid={invalid||undefined} aria-describedby={hint?`${id}-hint`:undefined} autoComplete={type==='password'?(id==='current'||fieldMockup.view==='login'?'current-password':'new-password'):type==='email'?'email':'off'} required/><>{hint&&<p id={`${id}-hint`}>{hint}</p>}</></div>}

